const r = $input.item.json;
let texto = 'No fue posible redactar el resumen automaticamente.';
let modelo = 'ninguno';

if (r.choices && r.choices[0]) { 
  texto = r.choices[0].message.content.trim(); 
  modelo = 'groq:' + (r.model || 'desconocido'); // v3: modelo real, no texto fijo
} else if (r.candidates && r.candidates[0]) { 
  texto = r.candidates[0].content.parts[0].text.trim(); 
  modelo = 'gemini:' + (r.modelVersion || 'desconocido');
}

const filas = $('Consultar historico (parametrizado)').all().map((i) => i.json);
const intencion = $('Parsear y validar intencion').first().json;
const resumen = $('Preparar prompt: respuesta').first().json.resumen_datos;

let valorDestacado = null;
if (intencion.parametro !== 'general') {
  const VALOR_POR_AGREGACION = {
    promedio: resumen.promedio,
    maximo: resumen.maximo,
    minimo: resumen.minimo,
  };
  valorDestacado = VALOR_POR_AGREGACION[intencion.agregacion] ?? null;
} else {
  valorDestacado = resumen.estado_general ?? null;
}

return {
  json: {
    ok: true,
    codigo_http: 200,
    tipo: 'datos',
    texto,
    modelo_usado: modelo,
    parametro: intencion.parametro,
    agregacion: intencion.agregacion,
    estacion: intencion.estacion,
    valor_destacado: valorDestacado,
    rango: { desde: intencion.desde, hasta: intencion.hasta },
    resumen: resumen,
    serie: filas.map((f) => ({ 
      x: f.medido_en, 
      y: f.valor, 
      parametro: f.parametro, 
      estacion: f.estacion 
    })),
  },
};

const intencion = $('Parsear y validar intencion').first().json;
const parametro = intencion.parametro;
const agregacion = intencion.agregacion;
const estacionPedida = intencion.estacion;
const filasAgregadas = $('Calcular agregacion (SQL)').all().map(item => item.json);

// Umbrales normativos oficiales ECA-aire (D.S. 003-2017-MINAM) en ug/m3
const UMBRALES_ECA = {
  pm25: { limite: 50, unidad: 'ug/m3' },
  pm10: { limite: 100, unidad: 'ug/m3' },
  so2:  { limite: 250, unidad: 'ug/m3' },
  no2:  { limite: 200, unidad: 'ug/m3' },
  o3:   { limite: 100, unidad: 'ug/m3' },
  co:   { limite: 10000, unidad: 'ug/m3' }
};

let contextoCalidad = '';
let resumenDatos = {};

if (parametro === 'general') {
  // Lógica oficial INCA: peor categoria entre contaminantes evaluados
  let peorEstado = 'Buena';
  let contaminanteCritico = null;
  let detalles = [];

  for (const fila of filasAgregadas) {
    const p = String(fila.parametro || '').toLowerCase();
    const eca = UMBRALES_ECA[p];
    if (!eca) continue;

    const prom = Number(fila.promedio);
    const ratio = (prom / eca.limite) * 100;
    let categoria = 'Buena';

    if (ratio > 100) categoria = 'Mala (supera ECA-aire)';
    else if (ratio > 50) categoria = 'Moderada';

    detalles.push(`${p.toUpperCase()}: promedio ${prom} ${eca.unidad} (Estado: ${categoria})`);

    if (categoria.startsWith('Mala')) {
      peorEstado = 'Mala';
      contaminanteCritico = p.toUpperCase();
    } else if (categoria === 'Moderada' && peorEstado !== 'Mala') {
      peorEstado = 'Moderada';
      if (!contaminanteCritico) contaminanteCritico = p.toUpperCase();
    }
  }

  contextoCalidad = `ESTADO GENERAL EVALUADO (INCA / D.S. 003-2017-MINAM): ${peorEstado.toUpperCase()}\n`
    + (contaminanteCritico ? `Contaminante critico que determina este estado: ${contaminanteCritico}\n` : '')
    + `Detalle de contaminantes evaluados:\n- ${detalles.join('\n- ')}`;

  resumenDatos = {
    estado_general: peorEstado,
    contaminante_critico: contaminanteCritico,
    detalles: filasAgregadas
  };
} else {
  // Consulta de un contaminante especifico
  const ag = filasAgregadas.find(f => String(f.parametro).toLowerCase() === parametro) || filasAgregadas[0] || {};
  const eca = UMBRALES_ECA[parametro];
  const prom = Number(ag.promedio || 0);
  const max = Number(ag.maximo || 0);
  const min = Number(ag.minimo || 0);
  const cant = Number(ag.cantidad || 0);

  let estadoNormativo = 'Dentro del estandar legal (Buena)';
  if (eca && prom > eca.limite) {
    estadoNormativo = `Supera el limite normativo ECA-aire (${eca.limite} ${eca.unidad})`;
  } else if (eca && prom > eca.limite * 0.5) {
    estadoNormativo = `Moderado (cercano al limite ECA-aire de ${eca.limite} ${eca.unidad})`;
  }

  contextoCalidad = `Parametro: ${parametro.toUpperCase()}\n`
    + `Promedio: ${prom} ${eca ? eca.unidad : ''}\n`
    + `Maximo: ${max} | Minimo: ${min}\n`
    + `Mediciones registradas: ${cant}\n`
    + `Evaluacion normativa: ${estadoNormativo}`;

  resumenDatos = {
    promedio: prom,
    maximo: max,
    minimo: min,
    cantidad: cant,
    evaluacion: estadoNormativo
  };
}

const sistema = 'Eres el asistente virtual ciudadano sobre calidad del aire de Lima, Peru. '
  + 'Tu mision es responder en maximo 3 o 4 oraciones de forma precisa, veridica y sin contradicciones. '
  + '\nREGLAS OBLIGATORIAS:'
  + '\n1. Si la consulta es GENERAL: Habla del estado global del aire (Buena, Moderada o Mala) segun el indice INCA. Menciona si todos cumplieron o cuales superaron la norma.'
  + '\n2. Si la consulta es sobre un CONTAMINANTE ESPECIFICO (ej. o3, pm25, co): '
  + '   - HABLA UNICAMENTE DE ESE GAS O PARTICULA. '
  + '   - PROHIBIDO decir "La calidad del aire es Buena" o "el aire es saludable", porque desconoces si otros contaminantes no consultados estan altos. '
  + '   - Di claramente: "Respecto al [parametro], sus niveles se encuentran [dentro del estandar / elevados] con un promedio de...". '
  + '   - Aclara que este resultado corresponde unicamente a ese parametro evaluado.'
  + '\n3. No agregues saludos efusivos ni frases como "¡Disfruta del aire!" si solo evaluaste un gas aislado.'
  + '\n4. No inventes cifras: usa solo las suministradas.';

const usuario = `Zona/Estacion consultada: ${estacionPedida}\n`
  + `Periodo: ${intencion.desde} a ${intencion.hasta}\n\n`
  + `${contextoCalidad}\n\n`
  + `Redacta la respuesta cumpliendo rigurosamente las reglas.`;

return [{
  json: {
    lf_inicio: new Date().toISOString(),   // Langfuse: hora de inicio de la llamada
    resumen_datos: resumenDatos,
    groq_payload: {
      model: 'openai/gpt-oss-120b',
      messages: [{ role: 'system', content: sistema }, { role: 'user', content: usuario }],
      temperature: 0.3,
      max_tokens: 500,
    },
    gemini_payload: {
      contents: [{ parts: [{ text: `${sistema}\n\n${usuario}` }] }],
      generationConfig: { temperature: 0.3, maxOutputTokens: 250 },
    },
  },
}];

