  (consulta_usuario, hash_consulta, filtros_extraidos, respuesta_texto, config_grafico, hit_cache)
VALUES ($1, encode(digest($1, 'sha256'), 'hex'), $2::jsonb, $3, '[]'::jsonb, false);

