const prep = $('Preparar prompt: intencion').first().json;
return { json: {
  flujo: 'B', paso: 'intencion', proveedor: 'groq',
  ejecucion: $execution.id,
  inicio: prep.lf_inicio,
  fin: new Date().toISOString(),
  prompt: prep.groq_payload?.messages,
  respuesta: $json,
  error: $json.error ? ($json.error.message ?? String($json.error)) : undefined,
} };

