const prep = $('Preparar prompt: intencion').first().json;
// el respaldo empieza cuando Groq falló; si ese nodo no corrió, usa el inicio del prompt
let ini = prep.lf_inicio;
try { ini = $('LF · Groq intencion (fallo)').first().json.fin || ini; } catch (e) {}
return { json: {
  flujo: 'B', paso: 'intencion', proveedor: 'gemini',
  es_fallback: true,
  ejecucion: $execution.id,
  inicio: ini,
  fin: new Date().toISOString(),
  prompt: prep.gemini_payload?.contents?.[0]?.parts?.[0]?.text,
  respuesta: $json,
  error: $json.error ? ($json.error.message ?? String($json.error)) : undefined,
} };

